import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(sys.stdin.readline())
    adj = [[] for _ in range(n+1)]
    for _ in range(n-1):
        x, y = map(int, sys.stdin.readline().split())
        adj[x].append(y)
        adj[y].append(x)

    parent = [0]*(n+1)
    depth = [0]*(n+1)
    size = [0]*(n+1)
    heavy = [-1]*(n+1)

    def dfs(u):
        size[u] = 1
        max_size = 0
        for v in adj[u]:
            if v != parent[u]:
                parent[v] = u
                depth[v] = depth[u] + 1
                dfs(v)
                size[u] += size[v]
                if size[v] > max_size:
                    max_size = size[v]
                    heavy[u] = v

    dfs(1)

    head = [0]*(n+1)
    pos = [0]*(n+1)
    current_pos = 1

    def decompose(u, h):
        nonlocal current_pos
        head[u] = h
        pos[u] = current_pos
        current_pos += 1
        if heavy[u] != -1:
            decompose(heavy[u], h)
        for v in adj[u]:
            if v != parent[u] and v != heavy[u]:
                decompose(v, v)

    decompose(1, 1)

    seg_tree = [0]*(4*n)

    def update(l, r, val, node=1, node_l=1, node_r=n):
        if r < node_l or node_r < l:
            return
        if l <= node_l and node_r <= r:
            seg_tree[node] += val
            return
        mid = (node_l + node_r) // 2
        update(l, r, val, 2*node, node_l, mid)
        update(l, r, val, 2*node+1, mid+1, node_r)

    def query(pos):
        res = 0
        while pos > 0:
            res += seg_tree[pos]
            pos -= pos & -pos
        return res

    def add_path(u, v, val):
        while head[u] != head[v]:
            if depth[head[u]] > depth[head[v]]:
                u, v = v, u
            update(pos[head[v]], pos[v], val)
            v = parent[head[v]]
        if depth[u] > depth[v]:
            u, v = v, u
        update(pos[u], pos[v], val)

    res = [0]*(n+1)
    m = int(sys.stdin.readline())
    for _ in range(m):
        v, d, x = map(int, sys.stdin.readline().split())
        if d == 0:
            res[v] += x
            continue
        q = deque()
        q.append((v, 0))
        while q:
            u, dist = q.popleft()
            if dist > d:
                continue
            res[u] += x
            for child in adj[u]:
                if child != parent[u]:
                    q.append((child, dist+1))

    for i in range(1, n+1):
        print(res[i], end=' ')

main()
